hooks.command:
python -c "
import sys, json, re
try:
    data = json.load(sys.stdin)
    cmd = data.get('tool_input', {}).get('command', '').lower()
    protected = ['expense_tracker.db', '.env', 'migrations']
    dangerous = re.compile(r'\b(rm|unlink|truncate|remove-item|del|erase|rd|rmdir|ri)\b')
    if dangerous.search(cmd):
        for p in protected:
            if p in cmd:
                print('BLOCKED: Cannot run destructive command on protected file: ' + p, file=sys.stderr)
                sys.exit(2)
except Exception as e:
    print('BLOCKED: protection hook failed, refusing to run: ' + str(e), file=sys.stderr)
    sys.exit(2)
"
